<template><main><section><div class="brand">♙　배스킨라빈스</div><p v-if="loading">초대 정보를 확인하고 있습니다.</p><form v-else-if="invite" @submit.prevent="join"><span class="approved">✓ 본점에서 지점 개설을 승인했습니다</span><h1>지점 회원가입</h1><p>{{ invite.managerName }} 점장님, {{ invite.branchName }} 계정을 설정하세요.</p><div class="info"><b>{{ invite.branchName }}</b><span>{{ invite.address }}</span><span>{{ invite.email }} · {{ invite.phone }}</span></div><label>아이디<input v-model="loginId" required minlength="4" placeholder="영문·숫자 4자 이상"></label><label>비밀번호<input v-model="password" required minlength="8" type="password" placeholder="8자 이상"></label><button>가입 완료</button><p v-if="error" class="error">{{ error }}</p></form><div v-else class="invalid"><h2>초대 URL을 사용할 수 없습니다</h2><p>{{ error }}</p><RouterLink to="/branch/login">로그인으로 이동</RouterLink></div></section></main></template>
<script setup>import{onMounted,ref}from'vue';import{signInWithEmailAndPassword}from'firebase/auth';import{useRoute,useRouter}from'vue-router';import http from'../../api/http';import{firebaseAuth}from'../../firebase';const route=useRoute(),router=useRouter(),loading=ref(true),invite=ref(null),loginId=ref(''),password=ref(''),error=ref('');onMounted(async()=>{try{invite.value=(await http.get(`/branch-auth/invites/${route.query.token}`)).data}catch(e){error.value=e.response?.data?.message||'만료되었거나 잘못된 URL입니다.'}finally{loading.value=false}});async function join(){try{await http.post('/branch-auth/join',{token:route.query.token,loginId:loginId.value,password:password.value});const credential=await signInWithEmailAndPassword(firebaseAuth,invite.value.email,password.value);const idToken=await credential.user.getIdToken();const{data}=await http.post('/branch-auth/firebase-session',{idToken});localStorage.setItem('branch-session',JSON.stringify(data));router.replace('/branch/dashboard')}catch(e){error.value=e.response?.data?.message||'계정을 만들 수 없습니다.'}}</script>
<style scoped>main{display:grid;min-height:100vh;padding:25px;place-items:center;background:#f2f5fa}section{width:min(560px,100%);padding:34px;background:#fff;border-radius:16px;box-shadow:0 18px 50px rgb(38 51 71/12%)}.brand{margin-bottom:30px;color:#6266ef;font-weight:900}.approved{display:inline-block;padding:7px 10px;color:#168c50;background:#e8f8f0;border-radius:7px;font-size:9px;font-weight:800}h1{margin:18px 0 5px}form>p{color:#87919e;font-size:10px}.info{display:grid;gap:5px;margin:20px 0;padding:14px;background:#f6f7fb;border-radius:9px}.info span{color:#7f8996;font-size:9px}label{display:grid;gap:6px;margin-top:14px;font-size:9px;font-weight:800}input{padding:12px;border:1px solid #dfe3e9;border-radius:7px}button{width:100%;margin-top:22px;padding:13px;color:#fff;border:0;background:#6266ef;border-radius:8px;font-weight:800}.error{color:#c83249}.invalid{text-align:center}.invalid a{color:#6266ef}</style>
